local TimberFeller = {}
local PRODUCTS = {
    pine_log = { name = "Borov hlod", pineCost = 1, time = 1, cost = 8, quality = 30, description = "Borov hlod iz gozda." },
    oak_log = { name = "Hrastov hlod", oakCost = 1, time = 2, cost = 18, quality = 50, prestige = 1, description = "Hrastov hlod za gradnjo." },
    ash_log = { name = "Jesenov hlod", ashCost = 1, time = 2, cost = 28, quality = 65, prestige = 2, description = "Jesenov hlod za loko in kopja." },
    yew_log = { name = "Tisov hlod", yewCost = 1, time = 3, cost = 65, quality = 80, prestige = 5, happiness = 1, description = "Tisov hlod za loku." },
    ebony_log = { name = "Ebenov hlod", ebonyCost = 1, time = 5, cost = 180, quality = 92, prestige = 12, happiness = 2, description = "Ebenov hlod za fine izdelke." },
    royal_grand_log = { name = "Kraljevski veliki hlod", ebonyCost = 1, yewCost = 1, goldCost = 1, jewelCost = 1, time = 9, cost = 800, quality = 100, prestige = 30, happiness = 6, description = "Veliki kraljevski hlod z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Gozdarska postaja", cost = { gold = 200, wood = 100 }, upkeep = 4, qualityBonus = 5 },
    lumber_camp = { name = "Lesna tabor", cost = { gold = 700, wood = 200, stone = 200, axe = 8 }, upkeep = 15, qualityBonus = 18 },
    timber_yard = { name = "Hlodovnica", cost = { gold = 1800, wood = 350, stone = 500, silver = 25, axe = 8 }, upkeep = 42, qualityBonus = 30 },
    royal_timber_atelier = { name = "Kraljevski atelje lesa", cost = { gold = 7500, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 150, qualityBonus = 55, prestigeBonus = 40 },
}
TimberFeller.pineStock = 22; TimberFeller.oakStock = 18; TimberFeller.ashStock = 14; TimberFeller.yewStock = 10; TimberFeller.ebonyStock = 6; TimberFeller.goldStock = 6; TimberFeller.jewelStock = 6
TimberFeller.productStock = {}; TimberFeller.buildings = {}; TimberFeller.maker = nil; TimberFeller.activeMaking = {}; TimberFeller.totalProducts = 0; TimberFeller.dayTimer = 0
function TimberFeller.init() TimberFeller.pineStock=22; TimberFeller.oakStock=18; TimberFeller.ashStock=14; TimberFeller.yewStock=10; TimberFeller.ebonyStock=6; TimberFeller.goldStock=6; TimberFeller.jewelStock=6; TimberFeller.productStock={}; TimberFeller.buildings={}; TimberFeller.maker=nil; TimberFeller.activeMaking={}; TimberFeller.totalProducts=0; TimberFeller.dayTimer=0; print("[TimberFeller] Royal Timber Feller System initialized (6 products, 4 buildings)") end
function TimberFeller.hireMaker(n,s) s=s or math.random(45,85); local c=420+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TimberFeller.maker={name=n or ("Gozdar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gozdar najet: %s (spretnost: %d)",TimberFeller.maker.name,s),"success") end; return true end
function TimberFeller.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TimberFeller.build(id) local ok,e=TimberFeller.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TimberFeller.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TimberFeller.getQualityBonus() local b=0; for _,bd in ipairs(TimberFeller.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TimberFeller.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.pineCost and TimberFeller.pineStock<(d.pineCost or 0) then return false,"Premalo bora" end; if d.oakCost and TimberFeller.oakStock<(d.oakCost or 0) then return false,"Premalo hrasta" end; if d.ashCost and TimberFeller.ashStock<(d.ashCost or 0) then return false,"Premalo jesena" end; if d.yewCost and TimberFeller.yewStock<(d.yewCost or 0) then return false,"Premalo tise" end; if d.ebonyCost and TimberFeller.ebonyStock<(d.ebonyCost or 0) then return false,"Premalo eben" end; if d.goldCost and TimberFeller.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TimberFeller.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #TimberFeller.buildings==0 then return false,"Potrebna delavnica" end; if not TimberFeller.maker then return false,"Potreben gozdar" end; return true end
function TimberFeller.make(pt,qty) qty=qty or 10; local ok,e=TimberFeller.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.pineCost then TimberFeller.pineStock=TimberFeller.pineStock-d.pineCost*qty end; if d.oakCost then TimberFeller.oakStock=TimberFeller.oakStock-d.oakCost*qty end; if d.ashCost then TimberFeller.ashStock=TimberFeller.ashStock-d.ashCost*qty end; if d.yewCost then TimberFeller.yewStock=TimberFeller.yewStock-d.yewCost*qty end; if d.ebonyCost then TimberFeller.ebonyStock=TimberFeller.ebonyStock-d.ebonyCost*qty end; if d.goldCost then TimberFeller.goldStock=TimberFeller.goldStock-d.goldCost*qty end; if d.jewelCost then TimberFeller.jewelStock=TimberFeller.jewelStock-d.jewelCost*qty end; local t=d.time; if TimberFeller.maker then t=math.max(1,t-math.floor(TimberFeller.maker.skill/12)) end; table.insert(TimberFeller.activeMaking,{id="timber_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,quality=d.quality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TimberFeller.completeMaking(m) local q=1.0+(TimberFeller.getQualityBonus()/100); if TimberFeller.maker then q=q+(TimberFeller.maker.skill/180) end; q=math.min(2.0,q); TimberFeller.productStock[m.productType]=(TimberFeller.productStock[m.productType] or 0)+m.quantity; TimberFeller.totalProducts=TimberFeller.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TimberFeller.maker then TimberFeller.maker.itemsMade=TimberFeller.maker.itemsMade+m.quantity; if math.random()<0.20 then TimberFeller.maker.skill=math.min(100,TimberFeller.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Hlod izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"timber.completed",{productName=m.productName,quality=m.quality}) end end
function TimberFeller.update(dt) if not _G.state then return end; TimberFeller.dayTimer=TimberFeller.dayTimer+dt; if TimberFeller.dayTimer>=30 then TimberFeller.dayTimer=0; for i=#TimberFeller.activeMaking,1,-1 do local m=TimberFeller.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TimberFeller.completeMaking(m); table.remove(TimberFeller.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TimberFeller.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TimberFeller.maker then tu=tu+10 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TimberFeller.getStats() return {pineStock=TimberFeller.pineStock,oakStock=TimberFeller.oakStock,ashStock=TimberFeller.ashStock,yewStock=TimberFeller.yewStock,ebonyStock=TimberFeller.ebonyStock,goldStock=TimberFeller.goldStock,jewelStock=TimberFeller.jewelStock,productStock=TimberFeller.productStock,numBuildings=#TimberFeller.buildings,hasMaker=TimberFeller.maker~=nil,makerName=TimberFeller.maker and TimberFeller.maker.name or "—",makerSkill=TimberFeller.maker and TimberFeller.maker.skill or 0,activeMaking=#TimberFeller.activeMaking,totalProducts=TimberFeller.totalProducts} end
return TimberFeller
